def solve_sequence(a0):
    # We are looking for a_0, a_1, ..., a_9 (10 terms)
    A = [a0]
    MAX_TERMS = 10

    print(f"--- Starting with a_0 = {a0} ---")

    # Helper function to safely get a_k
    def get_a(k, sequence):
        if k < 0:
            raise ValueError("Index must be non-negative")
        if k >= len(sequence):
            # If we need a term beyond what we have computed, we cannot proceed robustly
            raise IndexError(f"Index {k} needed, but only {len(sequence)} terms computed.")
        return sequence[k]

    # Iterate to compute a_1, a_2, ..., a_9
    for p in range(MAX_TERMS - 1):
        try:
            # We need a_{a_{a_p}}

            # Step 1: Get a_p
            ap = get_a(p, A)

            # Step 2: Get a_{a_p}
            a_ap = get_a(ap, A)

            # Step 3: Get a_{a_{a_p}}
            a_a_ap = get_a(a_ap, A)

            # Step 4: Calculate a_{p+1}
            a_p_plus_1 = a_a_ap - 1

            if a_p_plus_1 < 0:
                print(f"Failure at p={p}: Calculated a_{p+1} = {a_p_plus_1} (negative, not allowed).")
                return None # Sequence fails the non-negative constraint

            A.append(a_p_plus_1)

        except (ValueError, IndexError) as e:
            print(f"Failure at p={p}: {e}. Cannot compute a_{p+1}.")
            return None # Sequence fails due to index requirements

    print(f"Success. Sequence A = {A}")
    return A

# Test cases
results = {}
results['a_0=0'] = solve_sequence(0)
results['a_0=1'] = solve_sequence(1)
results['a_0=2'] = solve_sequence(2)

# Format output
for key, result in results.items():
    if result:
        print(f"Results for {key}: {result}")
    else:
        print(f"Results for {key}: Failed to compute within 10 terms.")
